// Throwaway: introspect Buffer's GraphQL schema to discover the engagement
// metrics fields that were just added. Run: npx tsx buffer-post/_introspect.ts
import { loadEnv, bufferApiQuery } from "./bufferPost";

const TYPE_QUERY = `
query IntrospectType($name: String!) {
  __type(name: $name) {
    name
    kind
    fields {
      name
      description
      type { ...TypeRef }
    }
  }
}
fragment TypeRef on __Type {
  kind name
  ofType { kind name ofType { kind name ofType { kind name } } }
}`;

const ALL_TYPES_QUERY = `
query { __schema { types { name kind } } }`;

function typeName(t: any): string {
  if (!t) return "?";
  if (t.name) return t.name;
  if (t.ofType) return `${t.kind === "LIST" ? "[" : ""}${typeName(t.ofType)}${t.kind === "NON_NULL" ? "!" : ""}`;
  return t.kind;
}

async function introspect(name: string) {
  const res = await bufferApiQuery<any>(TYPE_QUERY, { name });
  if (res.errors) {
    console.log(`\n### ${name}: ERROR ${res.errors.map((e) => e.message).join("; ")}`);
    return;
  }
  const t = res.data?.__type;
  if (!t) {
    console.log(`\n### ${name}: (type does not exist)`);
    return;
  }
  console.log(`\n### ${name} (${t.kind})`);
  for (const f of t.fields || []) {
    console.log(`  ${f.name}: ${typeName(f.type)}${f.description ? `   // ${f.description}` : ""}`);
  }
}

async function main() {
  loadEnv();

  // 1) List every type whose name hints at metrics/engagement/statistics.
  const all = await bufferApiQuery<any>(ALL_TYPES_QUERY);
  const hits = (all.data?.__schema?.types || [])
    .map((t: any) => t.name)
    .filter((n: string) =>
      /metric|engag|statistic|analytic|insight|performance|metadata|reach|impression/i.test(n || ""),
    );
  console.log("### Candidate types (name matches metric/engagement/etc):");
  console.log(hits.sort().join("\n"));

  // 2) Introspect the core types plus the wishlist names.
  const core = [
    "Post",
    "LinkedInPostMetadata",
    "MastodonPostMetadata",
    "BlueskyPostMetadata",
    ...hits,
  ];
  const seen = new Set<string>();
  for (const name of core) {
    if (seen.has(name)) continue;
    seen.add(name);
    await introspect(name);
  }
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

