import { loadEnv, bufferApiQuery } from "./bufferPost";

const ENUM_QUERY = `
query E($name: String!) {
  __type(name: $name) {
    name kind
    enumValues(includeDeprecated: true) { name description isDeprecated }
    inputFields { name description type { kind name ofType { kind name ofType { kind name ofType { kind name } } } } }
  }
}`;

function typeName(t: any): string {
  if (!t) return "?";
  if (t.name) return t.name + (t.kind === "NON_NULL" ? "!" : "");
  if (t.ofType) return `${t.kind === "LIST" ? "[" : ""}${typeName(t.ofType)}${t.kind === "LIST" ? "]" : ""}${t.kind === "NON_NULL" ? "!" : ""}`;
  return t.kind;
}

async function dump(name: string) {
  const res = await bufferApiQuery<any>(ENUM_QUERY, { name });
  if (res.errors) { console.log(`\n### ${name}: ERROR ${res.errors.map((e:any)=>e.message).join("; ")}`); return; }
  const t = res.data?.__type;
  if (!t) { console.log(`\n### ${name}: (missing)`); return; }
  console.log(`\n### ${name} (${t.kind})`);
  for (const v of t.enumValues || [])
    console.log(`  ${v.name}${v.isDeprecated ? " [DEPRECATED]" : ""}${v.description ? `   // ${v.description}` : ""}`);
  for (const f of t.inputFields || [])
    console.log(`  ${f.name}: ${typeName(f.type)}${f.description ? `   // ${f.description}` : ""}`);
}

async function main() {
  loadEnv();
  for (const n of [
    "PostMetricType",
    "PostMetricUnit",
    "PostStatus",
    "PostsFilter",
    "PostsInput",
    "DateRange",
    "DateRangeInput",
  ]) await dump(n);
}
