import { loadEnv, bufferApiQuery, CHANNEL_IDS } from "./bufferPost";

const ORG = `query { account { organizations { id } } }`;
// discover PostConnection pagination fields
const CONN = `query{__type(name:"PostConnection"){fields{name}}}`;

const SENT = `
query SentPosts($organizationId: OrganizationId!, $channelIds: [ChannelId!]!, $start: DateTime!, $after: String) {
  posts(
    input: {
      organizationId: $organizationId,
      filter: { channelIds: $channelIds, status: [sent], dueAt: { start: $start } },
      sort: [{ field: dueAt, direction: desc }]
    },
    first: 20,
    after: $after
  ) {
    edges { node {
      id text dueAt sentAt channelId metricsUpdatedAt
      metrics { type value unit name }
    } }
    pageInfo { hasNextPage endCursor }
  }
}`;

async function main() {
  loadEnv();
  const conn = await bufferApiQuery<any>(CONN);
  console.log("PostConnection fields:", (conn.data?.__type?.fields||[]).map((f:any)=>f.name).join(", "));

  const org = await bufferApiQuery<any>(ORG);
  const organizationId = org.data?.account?.organizations?.[0]?.id;
  console.log("org:", organizationId);

  const start = "2026-05-01T00:00:00.000Z";
  const res = await bufferApiQuery<any>(SENT, {
    organizationId,
    channelIds: Object.values(CHANNEL_IDS),
    start,
    after: null,
  });
  if (res.errors) { console.log("ERRORS:", JSON.stringify(res.errors, null, 2)); return; }
  const edges = res.data?.posts?.edges || [];
  console.log("pageInfo:", JSON.stringify(res.data?.posts?.pageInfo));
  console.log("returned", edges.length, "posts. Sample (first 6):\n");
  const rev = Object.fromEntries(Object.entries(CHANNEL_IDS).map(([k,v])=>[v,k]));
  for (const e of edges.slice(0, 6)) {
    const n = e.node;
    console.log(`[${rev[n.channelId]||n.channelId}] due=${n.dueAt} sent=${n.sentAt} mUpd=${n.metricsUpdatedAt}`);
    console.log(`  text: ${JSON.stringify((n.text||"").slice(0,70))}`);
    console.log(`  metrics: ${JSON.stringify(n.metrics)}`);
  }
}
main().catch(e=>{console.error(e);process.exit(1);});
EOF
