cat > buffer-post/_probe2.ts <<'EOF'
import { loadEnv, bufferApiQuery, CHANNEL_IDS } from "./bufferPost";
const ORG = `query { account { organizations { id } } }`;
const SENT = `
query SentPosts($organizationId: OrganizationId!, $channelIds: [ChannelId!]!, $start: DateTime!) {
  posts(input:{ organizationId:$organizationId, filter:{ channelIds:$channelIds, status:[sent], dueAt:{ start:$start } }, sort:[{ field:dueAt, direction:desc }] }, first:10) {
    edges { node {
      id text dueAt sentAt channelId
      metadata {
        __typename
        ... on MastodonPostMetadata { threadCount thread { text } }
        ... on BlueskyPostMetadata { threadCount thread { text } }
        ... on LinkedInPostMetadata { firstComment }
      }
    } }
    pageInfo { hasNextPage endCursor }
  }
}`;
async function main(){
  loadEnv();
  const org = await bufferApiQuery<any>(ORG);
  const organizationId = org.data?.account?.organizations?.[0]?.id;
  const rev = Object.fromEntries(Object.entries(CHANNEL_IDS).map(([k,v])=>[v,k]));
  for (const [name, id] of Object.entries(CHANNEL_IDS)) {
    const res = await bufferApiQuery<any>(SENT, { organizationId, channelIds:[id], start:"2026-06-01T00:00:00.000Z" });
    if (res.errors) { console.log(name, "ERR", JSON.stringify(res.errors)); continue; }
    const edges = res.data?.posts?.edges||[];
    console.log(`\n===== ${name}: ${edges.length} sent posts, pageInfo=${JSON.stringify(res.data?.posts?.pageInfo)}`);
    for (const e of edges.slice(0,3)) {
      const n = e.node;
      console.log(`  due=${n.dueAt} sent=${n.sentAt} type=${n.metadata?.__typename} threadCount=${n.metadata?.threadCount ?? "-"}`);
      console.log(`    text: ${JSON.stringify((n.text||"").slice(0,90))}`);
      if (n.metadata?.thread) console.log(`    threadParts: ${n.metadata.thread.length}`);
    }
  }
}
main().catch(e=>{console.error(e);process.exit(1);});
EOF
npx tsx buffer-post/_probe2.ts 2>&1 | head -80

