1	import * as fs from "fs";
2	import * as path from "path";
3	
4	// ============================================================================
5	// Types
6	// ============================================================================
7	
8	export interface LinkedInPostMetrics {
9	  reactions: number | null;
10	  comments: number | null;
11	  impressions: number | null;
12	  reach: number | null;
13	  engagementRate: string | null;
14	}
15	
16	export interface LinkedInPost {
17	  platform: "LinkedIn";
18	  postText: string;
19	  postedDateTime: string; // "YYYY-MM-DD HH:mm:ss"
20	  metrics: LinkedInPostMetrics;
21	}
22	
23	export interface LinkedInEngagement {
24	  reactions: number;
25	  comments: number;
26	  impressions: number;
27	  reach: number;
28	  engagementRate: string;
29	}
30	
31	export interface HistoryPost {
32	  id: number;
33	  created: string;
34	  posted: string; // "YYYY-MM-DDTHH:mm:ss"
35	  linkedin: string | null;
36	  mastodon: string[] | null;
37	  bluesky: string | null;
38	  topics: string[];
39	  links: string[];
40	  engagement: Record<string, unknown>;
41	}
42	
43	export interface HistoryData {
44	  posts: HistoryPost[];
45	}
46	
47	export interface MergeResult {
48	  data: HistoryData;
49	  updated: number;
50	  created: number;
51	}
52	
53	// ============================================================================
54	// Pure Functions (testable, no I/O)
55	// ============================================================================
56	
57	/**
58	 * Convert scraper date format "YYYY-MM-DD HH:mm:ss" to history format "YYYY-MM-DDTHH:mm:ss"
59	 */
60	export function scraperDateToHistoryDate(scraperDate: string): string {
61	  return scraperDate.replace(" ", "T");
62	}
63	
64	/**
65	 * Find all buff.ly URLs in text
66	 */
67	export function findBuffLyUrls(text: string): string[] {
68	  if (!text) return [];
69	  // Match https://buff.ly/... or http://buff.ly/... but not if preceded by other domain chars
70	  const regex = /(?<![a-zA-Z0-9])https?:\/\/buff\.ly\/[a-zA-Z0-9_-]+/g;
71	  const matches = text.match(regex);
72	  return matches || [];
73	}
74	
75	/**
76	 * Replace buff.ly URLs in text with their expanded versions from the urlMap
77	 */
78	export function replaceBuffLyUrls(
79	  text: string,
80	  urlMap: Map<string, string>,
81	): string {
82	  let result = text;
83	  for (const [shortUrl, expandedUrl] of urlMap) {
84	    result = result.split(shortUrl).join(expandedUrl);
85	  }
86	  return result;
87	}
88	
89	/**
90	 * Expand a single buff.ly URL by following the redirect.
91	 * Returns the expanded URL or the original if expansion fails.
92	 */
93	export async function expandBuffLyUrl(shortUrl: string): Promise<string> {
94	  try {
95	    const response = await fetch(shortUrl, {
96	      method: "HEAD",
97	      redirect: "follow",
98	    });
99	    return response.url;
100	  } catch {
101	    console.warn(`Failed to expand URL: ${shortUrl}`);
102	    return shortUrl;
103	  }
104	}
105	
106	/**
107	 * Expand all buff.ly URLs in the given text.
108	 * Returns text with buff.ly URLs replaced by their expanded versions.
109	 */
110	export async function expandBuffLyUrlsInText(text: string): Promise<string> {
111	  const buffLyUrls = findBuffLyUrls(text);
112	  if (buffLyUrls.length === 0) return text;
113	
114	  const urlMap = new Map<string, string>();
115	  for (const url of buffLyUrls) {
116	    const expanded = await expandBuffLyUrl(url);
117	    if (expanded !== url) {
118	      urlMap.set(url, expanded);
119	    }
120	  }
121	
122	  return replaceBuffLyUrls(text, urlMap);
123	}
124	
125	/**
126	 * Get the next available ID for a new post
127	 */
128	export function getNextId(posts: HistoryPost[]): number {
129	  if (posts.length === 0) return 1;
130	  return Math.max(...posts.map((p) => p.id)) + 1;
131	}
132	
133	/**
134	 * Find a matching post in history by posted datetime
135	 */
136	export function findMatchingPost(
137	  posts: HistoryPost[],
138	  postedDate: string,
139	): HistoryPost | undefined {
140	  return posts.find((p) => p.posted === postedDate);
141	}
142	
143	/**
144	 * Find the index of a history post whose linkedin text starts with the same
145	 * 60-character prefix (case-insensitive). Returns -1 if no match found.
146	 * Used as a fallback when datetime matching fails — e.g. for entries created
147	 * by bufferPost.ts that have posted="" but do have linkedin text.
148	 */
149	export function findIndexByLinkedInText(
150	  posts: HistoryPost[],
151	  text: string,
152	): number {
153	  const needle = text.substring(0, 60).toLowerCase();
154	  for (let i = 0; i < posts.length; i++) {
155	    const content = posts[i].linkedin;
156	    if (
157	      typeof content === "string" &&
158	      content.substring(0, 60).toLowerCase() === needle
159	    ) {
160	      return i;
161	    }
162	  }
163	  return -1;
164	}
165	
166	/**
167	 * Convert scraper metrics to history engagement format (nulls become 0)
168	 */
169	export function toHistoryEngagement(
170	  metrics: LinkedInPostMetrics,
171	): LinkedInEngagement {
172	  return {
173	    reactions: metrics.reactions ?? 0,
174	    comments: metrics.comments ?? 0,
175	    impressions: metrics.impressions ?? 0,
176	    reach: metrics.reach ?? 0,
177	    engagementRate: metrics.engagementRate ?? "0%",
178	  };
179	}
180	
181	/**
182	 * Update an existing history post with new LinkedIn data.
183	 * Returns a new object; does not mutate the original.
184	 */
185	export function updateExistingPost(
186	  existing: HistoryPost,
187	  scrapedPost: LinkedInPost,
188	): HistoryPost {
189	  return {
190	    ...existing,
191	    linkedin: scrapedPost.postText,
192	    engagement: {
193	      ...existing.engagement,
194	      linkedin: toHistoryEngagement(scrapedPost.metrics),
195	    },
196	  };
197	}
198	
199	/**
200	 * Create a new history post from a scraped LinkedIn post.
201	 */
202	export function createNewHistoryPost(
203	  id: number,
204	  scrapedPost: LinkedInPost,
205	): HistoryPost {
206	  const postedDate = scraperDateToHistoryDate(scrapedPost.postedDateTime);
207	  const createdDate = postedDate.split("T")[0];
208	
209	  return {
210	    id,
211	    created: createdDate,
212	    posted: postedDate,
213	    linkedin: scrapedPost.postText,
214	    mastodon: null,
215	    bluesky: null,
216	    topics: [],
217	    links: [],
218	    engagement: {
219	      linkedin: toHistoryEngagement(scrapedPost.metrics),
220	    },
221	  };
222	}
223	
224	/**
225	 * Merge scraped LinkedIn posts into history data.
226	 * - Matches by posted datetime
227	 * - Updates existing posts with new LinkedIn text and engagement
228	 * - Creates new posts for unmatched entries
229	 * Returns a new HistoryData object; does not mutate the input.
230	 */
231	export function mergeScrapedPosts(
232	  history: HistoryData,
233	  scrapedPosts: LinkedInPost[],
234	): MergeResult {
235	  let updated = 0;
236	  let created = 0;
237	
238	  // Build a map from posted datetime to index for efficient lookup
239	  const postsByDate = new Map<string, number>();
240	  history.posts.forEach((post, index) => {
241	    postsByDate.set(post.posted, index);
242	  });
243	
244	  // Start with copies of all existing posts
245	  const newPosts = history.posts.map((p) => ({ ...p }));
246	  let nextId = getNextId(history.posts);
247	
248	  for (const scrapedPost of scrapedPosts) {
249	    const historyDate = scraperDateToHistoryDate(scrapedPost.postedDateTime);
250	    const existingIndex = postsByDate.get(historyDate);
251	
252	    if (existingIndex !== undefined) {
253	      // Update existing post matched by datetime
254	      newPosts[existingIndex] = updateExistingPost(
255	        newPosts[existingIndex],
256	        scrapedPost,
257	      );
258	      updated++;
259	    } else {
260	      // Fallback: match by linkedin text prefix (handles bufferPost.ts entries
261	      // that have posted="" but do have linkedin text)
262	      const textIndex = findIndexByLinkedInText(newPosts, scrapedPost.postText);
263	      if (textIndex !== -1) {
264	        // Fill in posted/created if the matched entry has an empty posted date
265	        if (!newPosts[textIndex].posted) {
266	          newPosts[textIndex].posted = historyDate;
267	          newPosts[textIndex].created = historyDate.split("T")[0];
268	          postsByDate.set(historyDate, textIndex);
269	        }
270	        newPosts[textIndex] = updateExistingPost(
271	          newPosts[textIndex],
272	          scrapedPost,
273	        );
274	        updated++;
275	      } else {
276	        // Create new post
277	        const newPost = createNewHistoryPost(nextId, scrapedPost);
278	        newPosts.push(newPost);
279	        postsByDate.set(historyDate, newPosts.length - 1);
280	        nextId++;
281	        created++;
282	      }
283	    }
284	  }
285	
286	  // Sort by posted date, newest first
287	  newPosts.sort((a, b) => b.posted.localeCompare(a.posted));
288	
289	  return {
290	    data: { posts: newPosts },
291	    updated,
292	    created,
293	  };
294	}
295	
296	// ============================================================================
297	// I/O Wrappers
298	// ============================================================================
299	
300	const HISTORY_PATH = path.resolve("analytics", "history.json");
301	
302	export function readHistory(filePath: string = HISTORY_PATH): HistoryData {
303	  const content = fs.readFileSync(filePath, "utf-8");
304	  return JSON.parse(content) as HistoryData;
305	}
306	
307	export function writeHistory(
308	  data: HistoryData,
309	  filePath: string = HISTORY_PATH,
310	): void {
311	  fs.writeFileSync(filePath, JSON.stringify(data, null, 2) + "\n", "utf-8");
312	}
313	
314	/**
315	 * Entry point: read history.json, merge scraped posts, write back.
316	 */
317	export function syncScrapedPostsToHistory(scrapedPosts: LinkedInPost[]): void {
318	  const history = readHistory();
319	  const result = mergeScrapedPosts(history, scrapedPosts);
320	
321	  writeHistory(result.data);
322	
323	  console.log(
324	    `History sync: ${result.updated} updated, ${result.created} new (total: ${result.data.posts.length})`,
325	  );
326	}
327

