export interface LinkedInEngagement {
  reactions: number;
  comments: number;
  impressions: number;
  reach: number;
  engagementRate: string;
}

export interface HistoryPost {
  id: number;
  created: string;
  posted: string; // "YYYY-MM-DDTHH:mm:ss"
  linkedin: string | null;
  mastodon: string[] | null;
  bluesky: string | null;
  topics: string[];
  links: string[];
  engagement: Record<string, unknown>;
}

export interface HistoryData {
  posts: HistoryPost[];
}

export interface MergeResult {
  data: HistoryData;
  updated: number;
  created: number;
}

// ============================================================================
// Pure Functions (testable, no I/O)
// ============================================================================

/**
 * Convert scraper date format "YYYY-MM-DD HH:mm:ss" to history format "YYYY-MM-DDTHH:mm:ss"
 */
export function scraperDateToHistoryDate(scraperDate: string): string {
  return scraperDate.replace(" ", "T");
}

/**
 * Find all buff.ly URLs in text
 */
export function findBuffLyUrls(text: string): string[] {
  if (!text) return [];
  // Match https://buff.ly/... or http://buff.ly/... but not if preceded by other domain chars
  const regex = /(?<![a-zA-Z0-9])https?:\/\/buff\.ly\/[a-zA-Z0-9_-]+/g;
  const matches = text.match(regex);
  return matches || [];
}

/**
 * Replace buff.ly URLs in text with their expanded versions from the urlMap
 */
export function replaceBuffLyUrls(
  text: string,
  urlMap: Map<string, string>,
): string {
  let result = text;
  for (const [shortUrl, expandedUrl] of urlMap) {
    result = result.split(shortUrl).join(expandedUrl);
  }
  return result;
}

/**
 * Expand a single buff.ly URL by following the redirect.
 * Returns the expanded URL or the original if expansion fails.
 */
export async function expandBuffLyUrl(shortUrl: string): Promise<string> {
  try {
    const response = await fetch(shortUrl, {
      method: "HEAD",
      redirect: "follow",
    });
    return response.url;
  } catch {
    console.warn(`Failed to expand URL: ${shortUrl}`);
    return shortUrl;
  }
}

/**
 * Expand all buff.ly URLs in the given text.
 * Returns text with buff.ly URLs replaced by their expanded versions.
 */
export async function expandBuffLyUrlsInText(text: string): Promise<string> {
  const buffLyUrls = findBuffLyUrls(text);
  if (buffLyUrls.length === 0) return text;

  const urlMap = new Map<string, string>();
  for (const url of buffLyUrls) {
    const expanded = await expandBuffLyUrl(url);
    if (expanded !== url) {
      urlMap.set(url, expanded);
    }
  }

  return replaceBuffLyUrls(text, urlMap);
}

/**
 * Get the next available ID for a new post
 */
export function getNextId(posts: HistoryPost[]): number {
  if (posts.length === 0) return 1;
  return Math.max(...posts.map((p) => p.id)) + 1;
}

/**
 * Find a matching post in history by posted datetime
 */
export function findMatchingPost(
  posts: HistoryPost[],
  postedDate: string,
): HistoryPost | undefined {
  return posts.find((p) => p.posted === postedDate);
}

/**
 * Find the index of a history post whose linkedin text starts with the same
 * 60-character prefix (case-insensitive). Returns -1 if no match found.
 * Used as a fallback when datetime matching fails — e.g. for entries created
 * by bufferPost.ts that have posted="" but do have linkedin text.
 */
export function findIndexByLinkedInText(
  posts: HistoryPost[],
  text: string,
): number {
  const needle = text.substring(0, 60).toLowerCase();
  for (let i = 0; i < posts.length; i++) {
    const content = posts[i].linkedin;
    if (
      typeof content === "string" &&
      content.substring(0, 60).toLowerCase() === needle
    ) {
      return i;
    }
  }
  return -1;
}

/**
 * Convert scraper metrics to history engagement format (nulls become 0)
 */
export function toHistoryEngagement(
  metrics: LinkedInPostMetrics,
): LinkedInEngagement {
  return {
    reactions: metrics.reactions ?? 0,
    comments: metrics.comments ?? 0,
    impressions: metrics.impressions ?? 0,
    reach: metrics.reach ?? 0,
    engagementRate: metrics.engagementRate ?? "0%",
  };
}

/**
 * Update an existing history post with new LinkedIn data.
 * Returns a new object; does not mutate the original.
 */
export function updateExistingPost(
  existing: HistoryPost,
  scrapedPost: LinkedInPost,
): HistoryPost {
  return {
    ...existing,
    linkedin: scrapedPost.postText,
    engagement: {
      ...existing.engagement,
      linkedin: toHistoryEngagement(scrapedPost.metrics),
    },
  };
}

/**
 * Create a new history post from a scraped LinkedIn post.
 */
export function createNewHistoryPost(
  id: number,
  scrapedPost: LinkedInPost,
): HistoryPost {
  const postedDate = scraperDateToHistoryDate(scrapedPost.postedDateTime);
  const createdDate = postedDate.split("T")[0];

  return {
    id,
    created: createdDate,
    posted: postedDate,
    linkedin: scrapedPost.postText,
    mastodon: null,
    bluesky: null,
    topics: [],
    links: [],
    engagement: {
      linkedin: toHistoryEngagement(scrapedPost.metrics),
    },
  };
}

/**
 * Merge scraped LinkedIn posts into history data.
 * - Matches by posted datetime
 * - Updates existing posts with new LinkedIn text and engagement
 * - Creates new posts for unmatched entries
 * Returns a new HistoryData object; does not mutate the input.
 */
export function mergeScrapedPosts(
  history: HistoryData,
  scrapedPosts: LinkedInPost[],
): MergeResult {
  let updated = 0;
  let created = 0;

  // Build a map from posted datetime to index for efficient lookup
  const postsByDate = new Map<string, number>();
  history.posts.forEach((post, index) => {
    postsByDate.set(post.posted, index);
  });

  // Start with copies of all existing posts
  const newPosts = history.posts.map((p) => ({ ...p }));
  let nextId = getNextId(history.posts);

  for (const scrapedPost of scrapedPosts) {
    const historyDate = scraperDateToHistoryDate(scrapedPost.postedDateTime);
    const existingIndex = postsByDate.get(historyDate);

    if (existingIndex !== undefined) {
      // Update existing post matched by datetime
      newPosts[existingIndex] = updateExistingPost(
        newPosts[existingIndex],
        scrapedPost,
      );
      updated++;
    } else {
      // Fallback: match by linkedin text prefix (handles bufferPost.ts entries
      // that have posted="" but do have linkedin text)
      const textIndex = findIndexByLinkedInText(newPosts, scrapedPost.postText);
      if (textIndex !== -1) {
        // Fill in posted/created if the matched entry has an empty posted date
        if (!newPosts[textIndex].posted) {
          newPosts[textIndex].posted = historyDate;
          newPosts[textIndex].created = historyDate.split("T")[0];
          postsByDate.set(historyDate, textIndex);
        }
        newPosts[textIndex] = updateExistingPost(
          newPosts[textIndex],
          scrapedPost,
        );
        updated++;
      } else {
        // Create new post
        const newPost = createNewHistoryPost(nextId, scrapedPost);
        newPosts.push(newPost);
        postsByDate.set(historyDate, newPosts.length - 1);
        nextId++;
        created++;
      }
    }
  }

  // Sort by posted date, newest first
  newPosts.sort((a, b) => b.posted.localeCompare(a.posted));

  return {
    data: { posts: newPosts },
    updated,
    created,
  };
}

// ============================================================================
// I/O Wrappers
// ============================================================================

const HISTORY_PATH = path.resolve("analytics", "history.json");

export function readHistory(filePath: string = HISTORY_PATH): HistoryData {
  const content = fs.readFileSync(filePath, "utf-8");
  return JSON.parse(content) as HistoryData;
}

export function writeHistory(
  data: HistoryData,
  filePath: string = HISTORY_PATH,
): void {
  fs.writeFileSync(filePath, JSON.stringify(data, null, 2) + "\n", "utf-8");
}

/**
 * Entry point: read history.json, merge scraped posts, write back.
 */
export function syncScrapedPostsToHistory(scrapedPosts: LinkedInPost[]): void {
  const history = readHistory();
  const result = mergeScrapedPosts(history, scrapedPosts);

  writeHistory(result.data);

  console.log(
    `History sync: ${result.updated} updated, ${result.created} new (total: ${result.data.posts.length})`,
  );
}

