function findHistoryIndexByText(posts, scrapedText, platform) {
  const needle = scrapedText.substring(0, 60).toLowerCase();

  // Pass 1: match against the platform's own field
  for (let i = 0; i < posts.length; i++) {
    const post = posts[i];
    const content = post[platform];
    if (!content) continue;

    if (platform === "mastodon" && Array.isArray(content)) {
      // Match against first thread part
      if (content[0] && content[0].substring(0, 60).toLowerCase() === needle) {
        return i;
      }
    } else if (typeof content === "string") {
      if (content.substring(0, 60).toLowerCase() === needle) {
        return i;
      }
    }
  }

  // Pass 2: fallback — match against linkedin text
  for (let i = 0; i < posts.length; i++) {
    const content = posts[i].linkedin;
    if (
      typeof content === "string" &&
      content.substring(0, 60).toLowerCase() === needle
    ) {
      return i;
    }
  }

  return -1;
}

function syncMastodonToHistory(scrapedPosts) {
  const history = readHistory();
  let updated = 0;
  let skipped = 0;

  const newPosts = history.posts.map((p) => ({ ...p }));

  // Group scraped posts by thread: posts within 10 min are a thread.
  // Sort by time ascending first.
  const sorted = [...scrapedPosts].sort((a, b) =>
    a.postedDateTime.localeCompare(b.postedDateTime),
  );

  const threads = [];
  let currentThread = [];

  for (const post of sorted) {
    if (currentThread.length === 0) {
      currentThread.push(post);
    } else {
      const lastTime = new Date(
        currentThread[currentThread.length - 1].postedDateTime.replace(
          " ",
          "T",
        ),
      );
      const thisTime = new Date(post.postedDateTime.replace(" ", "T"));
      if (thisTime - lastTime <= 10 * 60 * 1000) {
        currentThread.push(post);
      } else {
        threads.push(currentThread);
        currentThread = [post];
      }
    }
  }
  if (currentThread.length > 0) threads.push(currentThread);

  // For each thread, sum metrics and match to history by first post's text
  for (const thread of threads) {
    const firstPostText = thread[0].text;
    const idx = findHistoryIndexByText(newPosts, firstPostText, "mastodon");

    if (idx === -1) {
      skipped += thread.length;
      continue;
    }

    // Sum metrics across thread parts
    let favorites = 0,
      replies = 0,
      reblogs = 0;
    for (const part of thread) {
      favorites += part.favorites ?? 0;
      replies += part.replies ?? 0;
      reblogs += part.reblogs ?? 0;
    }

    // Store mastodon thread text so future scrapes can match by platform field
    const mastodonParts = thread.map((part) => part.text);

    newPosts[idx] = {
      ...newPosts[idx],
      mastodon: newPosts[idx].mastodon || mastodonParts,
      engagement: {
        ...newPosts[idx].engagement,
        mastodon: { favorites, replies, reblogs },
      },
    };
    updated++;
  }

  newPosts.sort((a, b) => b.posted.localeCompare(a.posted));
  writeHistory({ posts: newPosts });
  console.log(
    `Mastodon sync: ${updated} threads matched, ${skipped} posts skipped (total: ${newPosts.length})`,
  );
}

function syncBlueskyToHistory(scrapedPosts) {
  const history = readHistory();
  let updated = 0;
  let skipped = 0;

  const newPosts = history.posts.map((p) => ({ ...p }));

  for (const scraped of scrapedPosts) {
    const idx = findHistoryIndexByText(newPosts, scraped.text, "bluesky");

    if (idx === -1) {
      skipped++;
      continue;
