// ============================================================================
// Pure metrics-mapping + history-merge logic (no I/O, no network — testable).
//
// Buffer's GraphQL API exposes per-post engagement as a normalized
// `metrics: [PostMetric!]` array on the Post type (requires the
// `insights:read` OAuth scope). Cross-network metrics use unified naming:
// Mastodon `favorites` and Bluesky `likes` both arrive as `reactions`;
// Mastodon `reblogs` and Bluesky `reposts` both arrive as `reposts`.
//
// history.json, however, stores platform-native vocabulary (mastodon
// favorites/replies/reblogs, bluesky likes/comments/reposts). These mappers
// translate the unified API metrics back into those existing shapes so the
// downstream analytics dashboard keeps working unchanged.
// ============================================================================

export type Platform = "LinkedIn" | "Mastodon" | "Bluesky";

/** One entry of Post.metrics from the Buffer API. */
export interface ApiPostMetric {
  type: string; // PostMetricType enum value, e.g. "reactions", "engagementRate"
  value: number; // Float; 0 when the network did not report the metric
  unit: string; // "count" | "percentage"
}

/** A sent post fetched from the Buffer API, normalized for merging. */
export interface ApiSentPost {
  id: string;
  channelId: string;
  platform: Platform;
  text: string; // root text (= first thread part for Mastodon/Bluesky)
  dueAt: string | null; // scheduled time, UTC ISO
  sentAt: string | null; // actual publish time, UTC ISO
  metricsUpdatedAt: string | null; // UTC ISO; null until Buffer's daily job runs
  metrics: ApiPostMetric[];
  threadParts: string[]; // additional thread parts (2..n), text only
}

export interface HistoryPost {
  id: number;
  created: string;
  posted: string; // "YYYY-MM-DDTHH:mm:ss" in America/New_York
  linkedin: string | null;
  linkedinComment?: string | null;
  mastodon: string[] | null;
  bluesky: string | null;
  topics: string[];
  links: string[];
  engagement: Record<string, unknown>;
}

export interface HistoryData {
  posts: HistoryPost[];
}

export interface MergeResult {
  data: HistoryData;
  updated: number;
  created: number;
  skipped: number;
}

// ----------------------------------------------------------------------------
// Metric extraction + platform mappers
// ----------------------------------------------------------------------------

/** Look up a metric value by its PostMetricType. Returns null if absent. */
export function metricValue(
  metrics: ApiPostMetric[],
  type: string,
): number | null {
  const m = metrics.find((x) => x.type === type);
  return m ? m.value : null;
}

/** Whole-number count, defaulting a missing metric to 0. */
function count(metrics: ApiPostMetric[], type: string): number {
  return Math.round(metricValue(metrics, type) ?? 0);
}

/** history.json stores engagement rate as an integer percentage string, e.g. "4%". */
export function formatEngagementRate(value: number | null): string {
  if (value === null) return "0%";
  return `${Math.round(value)}%`;
}

export interface LinkedInEngagement {
  reactions: number;
  comments: number;
  impressions: number;
  reach: number;
  engagementRate: string;
}

export function toLinkedInEngagement(
  metrics: ApiPostMetric[],
): LinkedInEngagement {
  return {
    reactions: count(metrics, "reactions"),
    comments: count(metrics, "comments"),
    impressions: count(metrics, "impressions"),
    reach: count(metrics, "reach"),
    engagementRate: formatEngagementRate(metricValue(metrics, "engagementRate")),
  };
}

export interface MastodonEngagement {
  favorites: number;
  replies: number;
  reblogs: number;
}

export function toMastodonEngagement(
  metrics: ApiPostMetric[],
): MastodonEngagement {
  return {
    favorites: count(metrics, "reactions"), // Mastodon favorites → unified reactions
    replies: count(metrics, "comments"),
    reblogs: count(metrics, "reposts"), // Mastodon reblogs → unified reposts
  };
}

export interface BlueskyEngagement {
  likes: number;
  comments: number;
  reposts: number;
}

export function toBlueskyEngagement(
  metrics: ApiPostMetric[],
): BlueskyEngagement {
  return {
    likes: count(metrics, "reactions"), // Bluesky likes → unified reactions
    comments: count(metrics, "comments"),
    reposts: count(metrics, "reposts"),
  };
}

export function engagementFor(
  platform: Platform,
  metrics: ApiPostMetric[],
): LinkedInEngagement | MastodonEngagement | BlueskyEngagement {
  switch (platform) {
    case "LinkedIn":
      return toLinkedInEngagement(metrics);
    case "Mastodon":
      return toMastodonEngagement(metrics);
    case "Bluesky":
      return toBlueskyEngagement(metrics);
  }
}

/** history.json engagement key for a platform ("linkedin" | "mastodon" | "bluesky"). */
export function engagementKey(platform: Platform): string {
  return platform.toLowerCase();
}

// ----------------------------------------------------------------------------
// Timestamps
// ----------------------------------------------------------------------------

const ET_FORMAT = new Intl.DateTimeFormat("en-CA", {
  timeZone: "America/New_York",
  year: "numeric",
  month: "2-digit",
  day: "2-digit",
  hour: "2-digit",
  minute: "2-digit",
  second: "2-digit",
  hour12: false,
});

/**
 * Convert a UTC ISO timestamp (Buffer's dueAt/sentAt) to the
 * "YYYY-MM-DDTHH:mm:ss" America/New_York format used by history.json's
 * `posted` field. DST is handled by Intl.
 */
export function utcToEtHistory(iso: string): string {
  const parts = Object.fromEntries(
    ET_FORMAT.formatToParts(new Date(iso)).map((p) => [p.type, p.value]),
  );
  // en-CA with hour12:false renders midnight as "24" in some engines.
  const hour = parts.hour === "24" ? "00" : parts.hour;
  return `${parts.year}-${parts.month}-${parts.day}T${hour}:${parts.minute}:${parts.second}`;
}

// ----------------------------------------------------------------------------
// Matching
// ----------------------------------------------------------------------------

/**
 * Find the index of a history post whose text matches `scrapedText` on the
 * first 60 characters (case-insensitive). Pass 1 matches the platform's own
 * field; pass 2 falls back to the linkedin field (covers posts whose
 * platform-specific text was never stored). Returns -1 if no match.
 */
export function findHistoryIndexByText(
  posts: HistoryPost[],
  scrapedText: string,
  platform: Platform,
): number {
  const needle = scrapedText.substring(0, 60).toLowerCase();
  const key = engagementKey(platform); // "linkedin" | "mastodon" | "bluesky"

  const prefixMatches = (content: unknown): boolean => {
    if (typeof content === "string") {
      return content.substring(0, 60).toLowerCase() === needle;
    }
    if (Array.isArray(content) && typeof content[0] === "string") {
      return content[0].substring(0, 60).toLowerCase() === needle;
    }
    return false;
  };

  // Pass 1: the platform's own field.
  for (let i = 0; i < posts.length; i++) {
    if (prefixMatches((posts[i] as Record<string, unknown>)[key])) return i;
  }
  // Pass 2: fall back to the linkedin field.
  for (let i = 0; i < posts.length; i++) {
    if (prefixMatches(posts[i].linkedin)) return i;
  }
  return -1;
}

function getNextId(posts: HistoryPost[]): number {
  if (posts.length === 0) return 1;
  return Math.max(...posts.map((p) => p.id)) + 1;
}

/** Prefer the scheduled slot (dueAt) for `posted`, falling back to sentAt. */
function postedDateFor(post: ApiSentPost): string | null {
  const iso = post.dueAt ?? post.sentAt;
  return iso ? utcToEtHistory(iso) : null;
}

// ----------------------------------------------------------------------------
// Merge
// ----------------------------------------------------------------------------

/**
 * Merge API-fetched engagement into history.json.
 *
 * For each post we match an existing history entry by text prefix (its own
 * platform field, then the linkedin field) and set `engagement[<platform>]`.
 * When the matched entry has an empty `posted`, it is back-filled from the
 * post's scheduled time (converted to ET), and the platform text field is
 * populated if missing.
 *
 * Unmatched LinkedIn posts are created as new history entries (LinkedIn is the
 * source of truth). Unmatched Mastodon/Bluesky posts are skipped — they are
 * adaptations that should already have an entry created at post time.
 *
 * Returns a new HistoryData; does not mutate the input.
 */
export function mergeMetricsIntoHistory(
  history: HistoryData,
  posts: ApiSentPost[],
): MergeResult {
  const newPosts = history.posts.map((p) => ({ ...p }));
  let nextId = getNextId(history.posts);
  let updated = 0;
  let created = 0;
  let skipped = 0;

  for (const post of posts) {
    const key = engagementKey(post.platform);
    const engagement = engagementFor(post.platform, post.metrics);
    const idx = findHistoryIndexByText(newPosts, post.text, post.platform);

    if (idx !== -1) {
      const existing = newPosts[idx];
      const postedDate = postedDateFor(post);

      // Back-fill posted/created for entries created by bufferPost.ts (posted="").
      if (!existing.posted && postedDate) {
        existing.posted = postedDate;
        existing.created = postedDate.split("T")[0];
      }

      // Store the platform's text if we don't already have it (enables future
      // matches by the platform's own field).
      if (post.platform === "Mastodon") {
        if (!existing.mastodon) existing.mastodon = [post.text, ...post.threadParts];
      } else if (post.platform === "Bluesky") {
        if (!existing.bluesky) existing.bluesky = post.text;
      } else if (!existing.linkedin) {
        existing.linkedin = post.text;
      }

      existing.engagement = { ...existing.engagement, [key]: engagement };
      updated++;
    } else if (post.platform === "LinkedIn") {
      const postedDate = postedDateFor(post) ?? "";
      newPosts.push({
        id: nextId++,
        created: postedDate ? postedDate.split("T")[0] : "",
        posted: postedDate,
        linkedin: post.text,
        linkedinComment: null,
        mastodon: null,
        bluesky: null,
        topics: [],
        links: [],
        engagement: { linkedin: engagement },
      });
      created++;
    } else {
      skipped++;
    }
  }

  // Newest first, matching the rest of the pipeline.
  newPosts.sort((a, b) => b.posted.localeCompare(a.posted));

  return { data: { posts: newPosts }, updated, created, skipped };
}

