// ============================================================================
// Sync post engagement metrics from Buffer's GraphQL API into history.json.
//
// Replaces the Playwright DOM scraper (buffer-export-via-playwright/scrapeAll.mjs).
// Buffer now exposes per-post metrics on the Post type via `metrics: [PostMetric!]`,
// gated behind the `insights:read` OAuth scope. This queries sent posts per
// channel over a rolling window, maps the normalized metrics back to the
// platform-native engagement shapes, and merges them into history.json.
//
// Paths are cwd-relative (`.env`, `analytics/history.json`), so — like
// `npm run batch` and the old scraper — run this from the agile-pain-relief-astro
// repo root.
// ============================================================================

import * as fs from "fs";
import * as path from "path";
import { loadEnv, bufferApiQuery, CHANNEL_IDS } from "./bufferPost";
import {
  ApiSentPost,
  HistoryData,
  Platform,
  mergeMetricsIntoHistory,
} from "./metricsSync";

const DEFAULT_WEEKS = 6; // matches the old scraper's cutoff window
const PAGE_SIZE = 100;
const MAX_PAGES = 50; // safety backstop (5,000 posts/channel)

const PLATFORM_BY_CHANNEL: Record<string, Platform> = Object.fromEntries(
  Object.entries(CHANNEL_IDS).map(([platform, id]) => [id, platform as Platform]),
) as Record<string, Platform>;

// ----------------------------------------------------------------------------
// GraphQL
// ----------------------------------------------------------------------------

const ORG_QUERY = `query { account { organizations { id } } }`;

const SENT_POSTS_QUERY = `
query SentPosts(
  $organizationId: OrganizationId!,
  $channelId: ChannelId!,
  $start: DateTime!,
  $after: String
) {
  posts(
    input: {
      organizationId: $organizationId,
      filter: { channelIds: [$channelId], status: [sent], dueAt: { start: $start } },
      sort: [{ field: dueAt, direction: desc }]
    },
    first: ${PAGE_SIZE},
    after: $after
  ) {
    edges {
      node {
        id
        channelId
        text
        dueAt
        sentAt
        metricsUpdatedAt
        metrics { type value unit }
        metadata {
          __typename
          ... on MastodonPostMetadata { thread { text } }
          ... on BlueskyPostMetadata { thread { text } }
        }
      }
    }
    pageInfo { hasNextPage endCursor }
  }
}`;

interface GraphQLError {
  message: string;
  extensions?: { code?: string; requiredScopes?: string[] };
}

/** Buffer returns partial data for missing scopes, so metric fields must be
 * validated separately from a hard request failure. */
function findScopeError(errors?: GraphQLError[]): GraphQLError | undefined {
  return errors?.find(
    (e) =>
      e.extensions?.code === "INSUFFICIENT_SCOPE" ||
      /insights:read/i.test(e.message),
  );
}

class ScopeError extends Error {}

function assertNoScopeError(errors?: GraphQLError[]): void {
  const scope = findScopeError(errors);
  if (scope) {
    const granted = /Granted: ([^"]+)/.exec(scope.message)?.[1]?.trim();
    throw new ScopeError(
      "Buffer API token is missing the 'insights:read' scope required for post metrics.\n" +
        (granted ? `  Granted scopes: ${granted}\n` : "") +
        "  Create/re-authorize a token that includes 'insights:read' at Buffer's\n" +
        "  developer settings and update BUFFER_API_TOKEN in .env.",
    );
  }
}

async function fetchOrganizationId(): Promise<string> {
  const res = await bufferApiQuery<{
    account?: { organizations?: Array<{ id: string }> };
  }>(ORG_QUERY);
  if (res.errors) {
    throw new Error(
      `Could not fetch organization id: ${res.errors.map((e) => e.message).join("; ")}`,
    );
  }
  const orgId = res.data?.account?.organizations?.[0]?.id;
  if (!orgId) throw new Error("No organization id on this Buffer account");
  return orgId;
}

interface RawNode {
  id: string;
  channelId: string;
  text: string;
  dueAt: string | null;
  sentAt: string | null;
  metricsUpdatedAt: string | null;
  metrics: Array<{ type: string; value: number; unit: string }> | null;
  metadata?: { thread?: Array<{ text: string }> | null } | null;
}

/** Fetch every sent post for one channel since `start`, following pagination. */
async function fetchSentPostsForChannel(
  organizationId: string,
  channelId: string,
  start: string,
): Promise<ApiSentPost[]> {
  const platform = PLATFORM_BY_CHANNEL[channelId];
  const out: ApiSentPost[] = [];
  let after: string | null = null;

  for (let page = 0; page < MAX_PAGES; page++) {
    const res = await bufferApiQuery<{
      posts?: {
        edges?: Array<{ node?: RawNode }>;
        pageInfo?: { hasNextPage?: boolean; endCursor?: string | null };
      };
    }>(SENT_POSTS_QUERY, { organizationId, channelId, start, after });

    // A scope error means metrics came back null across the board — abort loudly
    // rather than silently writing zeros.
    assertNoScopeError(res.errors as GraphQLError[] | undefined);
    if (res.errors) {
      throw new Error(
        `Buffer posts query failed for ${platform}: ${res.errors
          .map((e) => e.message)
          .join("; ")}`,
      );
    }

    const edges = res.data?.posts?.edges ?? [];
    for (const edge of edges) {
      const n = edge.node;
      if (!n) continue;
      out.push({
        id: n.id,
        channelId: n.channelId,
        platform,
        text: n.text ?? "",
        dueAt: n.dueAt ?? null,
        sentAt: n.sentAt ?? null,
        metricsUpdatedAt: n.metricsUpdatedAt ?? null,
        metrics: n.metrics ?? [],
        threadParts: (n.metadata?.thread ?? []).map((t) => t.text),
      });
    }

    const info = res.data?.posts?.pageInfo;
    if (!info?.hasNextPage || !info.endCursor) break;
    after = info.endCursor;
  }

  return out;
}

// ----------------------------------------------------------------------------
// history.json I/O (cwd-relative, same path/format as the rest of the pipeline)
// ----------------------------------------------------------------------------

const HISTORY_PATH = path.resolve("analytics", "history.json");

function readHistory(): HistoryData {
  return JSON.parse(fs.readFileSync(HISTORY_PATH, "utf-8")) as HistoryData;
}

function writeHistory(data: HistoryData): void {
  fs.writeFileSync(HISTORY_PATH, JSON.stringify(data, null, 2) + "\n", "utf-8");
}

// ----------------------------------------------------------------------------
// CLI
// ----------------------------------------------------------------------------

interface Options {
  dryRun: boolean;
  weeks: number;
}

export function parseArgs(argv: string[]): Options {
  const opts: Options = { dryRun: false, weeks: DEFAULT_WEEKS };
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === "--dry-run") opts.dryRun = true;
