import { describe, it, expect } from "vitest";
import {
  ApiPostMetric,
  ApiSentPost,
  HistoryData,
  HistoryPost,
  formatEngagementRate,
  metricValue,
  toLinkedInEngagement,
  toMastodonEngagement,
  toBlueskyEngagement,
  utcToEtHistory,
  findHistoryIndexByText,
  mergeMetricsIntoHistory,
} from "./metricsSync";

const m = (type: string, value: number, unit = "count"): ApiPostMetric => ({
  type,
  value,
  unit,
});

function post(overrides: Partial<ApiSentPost>): ApiSentPost {
  return {
    id: "p1",
    channelId: "c",
    platform: "LinkedIn",
    text: "",
    dueAt: null,
    sentAt: null,
    metricsUpdatedAt: null,
    metrics: [],
    threadParts: [],
    ...overrides,
  };
}

function historyPost(overrides: Partial<HistoryPost>): HistoryPost {
  return {
    id: 1,
    created: "2026-07-01",
    posted: "2026-07-01T13:30:00",
    linkedin: null,
    mastodon: null,
    bluesky: null,
    topics: [],
    links: [],
    engagement: {},
    ...overrides,
  };
}

describe("metricValue", () => {
  it("returns the value when present, null when absent", () => {
    const metrics = [m("reactions", 6), m("comments", 1)];
    expect(metricValue(metrics, "reactions")).toBe(6);
    expect(metricValue(metrics, "reach")).toBeNull();
  });
});

describe("formatEngagementRate", () => {
  it("rounds to an integer percentage string", () => {
    expect(formatEngagementRate(4.2)).toBe("4%");
    expect(formatEngagementRate(4.8)).toBe("5%");
  });
  it("defaults null to 0%", () => {
    expect(formatEngagementRate(null)).toBe("0%");
  });
});

describe("platform mappers", () => {
  it("maps LinkedIn metrics directly", () => {
    const metrics = [
      m("reactions", 6),
      m("comments", 1),
      m("impressions", 165),
      m("reach", 110),
      m("engagementRate", 4, "percentage"),
    ];
    expect(toLinkedInEngagement(metrics)).toEqual({
      reactions: 6,
      comments: 1,
      impressions: 165,
      reach: 110,
      engagementRate: "4%",
    });
  });

  it("defaults missing LinkedIn metrics to 0 / 0%", () => {
    expect(toLinkedInEngagement([])).toEqual({
      reactions: 0,
      comments: 0,
      impressions: 0,
      reach: 0,
      engagementRate: "0%",
    });
  });

  it("maps unified reactions/comments/reposts to Mastodon vocabulary", () => {
    const metrics = [m("reactions", 3), m("comments", 2), m("reposts", 1)];
    expect(toMastodonEngagement(metrics)).toEqual({
      favorites: 3,
      replies: 2,
      reblogs: 1,
    });
  });

  it("maps unified reactions/comments/reposts to Bluesky vocabulary", () => {
    const metrics = [m("reactions", 5), m("comments", 1), m("reposts", 2)];
    expect(toBlueskyEngagement(metrics)).toEqual({
      likes: 5,
      comments: 1,
      reposts: 2,
    });
  });
});

describe("utcToEtHistory", () => {
  it("converts UTC to America/New_York in history format (EDT)", () => {
    expect(utcToEtHistory("2026-07-15T17:30:00.000Z")).toBe(
      "2026-07-15T13:30:00",
    );
  });
  it("handles standard time (EST, winter)", () => {
    // 2026-01-15 18:30Z = 13:30 EST (UTC-5)
    expect(utcToEtHistory("2026-01-15T18:30:00.000Z")).toBe(
      "2026-01-15T13:30:00",
    );
  });
});

describe("findHistoryIndexByText", () => {
  const posts: HistoryPost[] = [
    historyPost({ id: 1, linkedin: "Alpha post about scrum and agility here now" }),
    historyPost({
      id: 2,
      mastodon: ["Bravo post about deskilling and AI in radiology today"],
    }),
    historyPost({ id: 3, bluesky: "Charlie post covering the sprint backlog myth" }),
  ];

  it("matches the platform's own field first (case-insensitive, 60-char)", () => {
    expect(
      findHistoryIndexByText(posts, "bravo POST about deskilling and AI in radiology today", "Mastodon"),
    ).toBe(1);
  });

  it("falls back to the linkedin field", () => {
    expect(
      findHistoryIndexByText(posts, "Alpha post about scrum and agility here now", "Bluesky"),
    ).toBe(0);
  });

  it("returns -1 with no match", () => {
    expect(findHistoryIndexByText(posts, "nothing matches this text", "LinkedIn")).toBe(-1);
  });
});

describe("mergeMetricsIntoHistory", () => {
  it("updates a matched entry's engagement without touching authored text", () => {
    const history: HistoryData = {
      posts: [historyPost({ id: 1, linkedin: "Deskilling: losing skills you stop practising, a note" })],
    };
    const result = mergeMetricsIntoHistory(history, [
      post({
        platform: "LinkedIn",
        text: "Deskilling: losing skills you stop practising, a note",
        dueAt: "2026-07-15T17:30:00.000Z",
        metrics: [m("reactions", 6), m("comments", 1), m("impressions", 165), m("reach", 110), m("engagementRate", 4, "percentage")],
      }),
    ]);
    expect(result.updated).toBe(1);
    expect(result.created).toBe(0);
    expect(result.data.posts[0].linkedin).toBe("Deskilling: losing skills you stop practising, a note");
    expect(result.data.posts[0].engagement.linkedin).toEqual({
      reactions: 6,
      comments: 1,
      impressions: 165,
      reach: 110,
      engagementRate: "4%",
    });
  });

  it("back-fills empty posted/created from dueAt (ET) on match", () => {
    const history: HistoryData = {
      posts: [historyPost({ id: 1, posted: "", created: "", linkedin: "A freshly posted item awaiting its metrics data now" })],
    };
    const result = mergeMetricsIntoHistory(history, [
      post({ platform: "LinkedIn", text: "A freshly posted item awaiting its metrics data now", dueAt: "2026-07-15T17:30:00.000Z" }),
    ]);
    expect(result.data.posts[0].posted).toBe("2026-07-15T13:30:00");
    expect(result.data.posts[0].created).toBe("2026-07-15");
  });

  it("stores mastodon thread parts when the field is empty", () => {
    const history: HistoryData = {
      posts: [historyPost({ id: 1, linkedin: "Root LinkedIn version of the deskilling story here ok" })],
    };
    const result = mergeMetricsIntoHistory(history, [
      post({
        platform: "Mastodon",
        text: "Root LinkedIn version of the deskilling story here ok",
        threadParts: ["part two", "part three"],
        metrics: [m("reactions", 3)],
      }),
    ]);
    expect(result.data.posts[0].mastodon).toEqual([
      "Root LinkedIn version of the deskilling story here ok",
      "part two",
      "part three",
    ]);
    expect(result.data.posts[0].engagement.mastodon).toEqual({ favorites: 3, replies: 0, reblogs: 0 });
  });

  it("creates a new entry for an unmatched LinkedIn post", () => {
    const history: HistoryData = { posts: [historyPost({ id: 7 })] };
    const result = mergeMetricsIntoHistory(history, [
      post({ platform: "LinkedIn", text: "A brand new organic linkedin post not in history yet", dueAt: "2026-07-10T14:00:00.000Z", metrics: [m("reactions", 2)] }),
    ]);
    expect(result.created).toBe(1);
    const created = result.data.posts.find((p) => p.id === 8);
    expect(created?.linkedin).toBe("A brand new organic linkedin post not in history yet");
    expect(created?.posted).toBe("2026-07-10T10:00:00");
  });

  it("skips an unmatched Mastodon/Bluesky post", () => {
    const history: HistoryData = { posts: [historyPost({ id: 1, linkedin: "Unrelated existing content" })] };
    const result = mergeMetricsIntoHistory(history, [
      post({ platform: "Bluesky", text: "Some bluesky-only post with no history entry to match", metrics: [m("reactions", 1)] }),
    ]);
    expect(result.updated).toBe(0);
    expect(result.created).toBe(0);
    expect(result.skipped).toBe(1);
    expect(result.data.posts).toHaveLength(1);
  });

  it("does not mutate the input history", () => {
    const history: HistoryData = { posts: [historyPost({ id: 1, linkedin: "Immutable check content stays untouched by the merge fn" })] };
    const snapshot = JSON.stringify(history);
    mergeMetricsIntoHistory(history, [
      post({ platform: "LinkedIn", text: "Immutable check content stays untouched by the merge fn", metrics: [m("reactions", 9)] }),
    ]);
    expect(JSON.stringify(history)).toBe(snapshot);
  });

  it("sorts output newest-first by posted", () => {
    const history: HistoryData = {
      posts: [
        historyPost({ id: 1, posted: "2026-07-01T13:30:00", linkedin: "older" }),
        historyPost({ id: 2, posted: "2026-07-10T13:30:00", linkedin: "newer" }),
      ],
    };
    const result = mergeMetricsIntoHistory(history, []);
    expect(result.data.posts.map((p) => p.id)).toEqual([2, 1]);
  });
});

