/**
 * Find the history entry for an API post. Three passes, in order:
 *   1. text prefix of the platform's own field,
 *   2. text prefix of the linkedin field,
 *   3. exact scheduled-slot match — `dueAt` (converted to ET) equals `posted`.
 *
 * Pass 3 relies on `dueAt` being identical across all three channels for a
 * single content piece: once LinkedIn is merged first (back-filling `posted`
 * from its slot), the Mastodon/Bluesky adaptations of that content land on the
 * same entry even when their adapted text was never stored. `sentAt` is
 * deliberately not used — it jitters by seconds between channels. Exact
 * equality avoids matching organic native posts, whose times are off-slot.
 */
export function matchHistoryIndex(
  posts: HistoryPost[],
  post: ApiSentPost,
): number {
  const byText = findHistoryIndexByText(posts, post.text, post.platform);
  if (byText !== -1) return byText;

  if (post.dueAt) {
    const et = utcToEtHistory(post.dueAt);
    const bySlot = posts.findIndex((p) => p.posted === et);
    if (bySlot !== -1) return bySlot;
  }
  return -1;
}

