        dueAt: n.dueAt ?? null,
        sentAt: n.sentAt ?? null,
        metricsUpdatedAt: n.metricsUpdatedAt ?? null,
        metrics: n.metrics ?? [],
        threadParts: (n.metadata?.thread ?? []).map((t) => t.text),
      });
    }

    const info = res.data?.posts?.pageInfo;
    if (!info?.hasNextPage || !info.endCursor) break;
    after = info.endCursor;
  }

  return out;
}

// ----------------------------------------------------------------------------
// history.json I/O (cwd-relative, same path/format as the rest of the pipeline)
// ----------------------------------------------------------------------------

const HISTORY_PATH = path.resolve("analytics", "history.json");

function readHistory(): HistoryData {
  return JSON.parse(fs.readFileSync(HISTORY_PATH, "utf-8")) as HistoryData;
}

function writeHistory(data: HistoryData): void {
  fs.writeFileSync(HISTORY_PATH, JSON.stringify(data, null, 2) + "\n", "utf-8");
}

// ----------------------------------------------------------------------------
// CLI
// ----------------------------------------------------------------------------

interface Options {
  dryRun: boolean;
  weeks: number;
}

export function parseArgs(argv: string[]): Options {
  const opts: Options = { dryRun: false, weeks: DEFAULT_WEEKS };
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === "--dry-run") opts.dryRun = true;
    else if (arg === "--weeks") opts.weeks = Number(argv[++i]);
    else if (arg.startsWith("--weeks=")) opts.weeks = Number(arg.split("=")[1]);
  }
  if (!Number.isFinite(opts.weeks) || opts.weeks <= 0) opts.weeks = DEFAULT_WEEKS;
  return opts;
}

async function main(): Promise<void> {
  const opts = parseArgs(process.argv.slice(2));
  loadEnv();

  const start = new Date(
    Date.now() - opts.weeks * 7 * 24 * 60 * 60 * 1000,
  ).toISOString();
  console.log(
    `Fetching sent-post metrics since ${start} (${opts.weeks} weeks)${opts.dryRun ? " [dry-run]" : ""}`,
  );

  const organizationId = await fetchOrganizationId();

  const allPosts: ApiSentPost[] = [];
  for (const [platform, channelId] of Object.entries(CHANNEL_IDS)) {
    const posts = await fetchSentPostsForChannel(organizationId, channelId, start);
    const withMetrics = posts.filter((p) => p.metrics.length > 0).length;
    console.log(
      `  ${platform}: ${posts.length} sent posts (${withMetrics} with metrics)`,
    );
    allPosts.push(...posts);
  }

  const history = readHistory();
  const result = mergeMetricsIntoHistory(history, allPosts);
  console.log(
    `Merge: ${result.updated} updated, ${result.created} new, ${result.skipped} unmatched (total: ${result.data.posts.length})`,
  );

  if (opts.dryRun) {
    console.log("Dry run — history.json not written.");
    return;
  }
  writeHistory(result.data);
  console.log(`Wrote ${HISTORY_PATH}`);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main().catch((err) => {
    if (err instanceof ScopeError) {
      console.error(`\n${err.message}`);
    } else {
      console.error(err);
    }
    process.exit(1);
  });
}

