    else if (arg === "--since") opts.since = argv[++i] ?? null;
    else if (arg.startsWith("--since=")) opts.since = arg.split("=")[1];
  }
  if (!Number.isFinite(opts.weeks) || opts.weeks <= 0) opts.weeks = DEFAULT_WEEKS;
  return opts;
}

/** Resolve the window start as a UTC ISO string. `--since YYYY-MM-DD` wins;
