describe("parseArgs / resolveStart", () => {
  const NOW = Date.parse("2026-07-15T00:00:00.000Z");

  it("defaults to a 6-week window", () => {
    const opts = parseArgs([]);
    expect(opts).toEqual({ dryRun: false, weeks: 6, since: null });
    expect(resolveStart(opts, NOW)).toBe("2026-06-03T00:00:00.000Z");
  });

  it("parses --dry-run, --weeks and --since", () => {
    expect(parseArgs(["--dry-run", "--weeks", "12"])).toMatchObject({ dryRun: true, weeks: 12 });
    expect(parseArgs(["--since", "2024-01-01"]).since).toBe("2024-01-01");
    expect(parseArgs(["--since=2024-01-01"]).since).toBe("2024-01-01");
  });

  it("lets --since override the weeks window", () => {
    const opts = parseArgs(["--since", "2024-01-01", "--weeks", "6"]);
    expect(resolveStart(opts, NOW)).toBe("2024-01-01T00:00:00.000Z");
  });

  it("throws on an unparseable --since date", () => {
    expect(() => resolveStart(parseArgs(["--since", "nonsense"]), NOW)).toThrow(/Invalid --since/);
  });
});

